    ('Lead', 'attached', '{"walkthroughs":{"some":{"performers":{"some":{"user_id":"{{userId}}"}}}}}'::jsonb),
    ('Job', 'own_leads', '{"estimate":{"lead":{"lead_assignees":{"some":{"user_id":"{{userId}}"}}}}}'::jsonb),
    ('Job', 'attached', '{"visits":{"some":{"assignees":{"some":{"user_id":"{{userId}}"}}}}}'::jsonb),
    ('Job', 'attached', '{"assignees":{"some":{"user_id":"{{userId}}"}}}'::jsonb),
    ('Job', 'attached', '{"OR":[{"visits":{"some":{"assignees":{"some":{"user_id":"{{userId}}"}}}}},{"created_by_id":"{{userId}}"}]}'::jsonb),
    ('Job', 'attached', '{"OR":[{"assignees":{"some":{"user_id":"{{userId}}"}}},{"created_by_id":"{{userId}}"}]}'::jsonb),
    ('Estimate', 'own_leads', '{"lead":{"lead_assignees":{"some":{"user_id":"{{userId}}"}}}}'::jsonb),
    ('Estimate', 'own_leads', '{"OR":[{"lead":{"lead_assignees":{"some":{"user_id":"{{userId}}"}}}},{"AND":[{"lead_id":null},{"created_by":"{{userId}}"}]}]}'::jsonb),
    ('Invoice', 'own_leads', '{"job":{"estimate":{"lead":{"lead_assignees":{"some":{"user_id":"{{userId}}"}}}}}}'::jsonb),
    ('Invoice', 'attached', '{"job":{"visits":{"some":{"assignees":{"some":{"user_id":"{{userId}}"}}}}}}'::jsonb),
    ('Invoice', 'attached', '{"job":{"assignees":{"some":{"user_id":"{{userId}}"}}}}'::jsonb)
  ) v(subject, class, cond);
