  ) v(action, subject, how);
  -- @end
  ANALYZE s01_22_mapped;

  -- @step s01_22_builtin
  CREATE TEMP TABLE s01_22_builtin ON COMMIT DROP AS
  SELECT o.id AS organization_id, r.role_key FROM organizations o CROSS JOIN (VALUES ('ADMIN'), ('SALES'), ('DISPATCHER'), ('TECHNICIAN')) r(role_key);
  -- @end
  ANALYZE s01_22_builtin;

  -- @step s01_22_custom
  CREATE TEMP TABLE s01_22_custom ON COMMIT DROP AS
  SELECT c.id AS custom_role_id, c.organization_id, c.key AS role_key, c.base_role::text AS base_role, c.made_from_blank
  FROM custom_roles c
  WHERE NOT EXISTS (SELECT 1 FROM permission_role_switches s WHERE s.organization_id = c.organization_id AND s.role_key = c.key);
  -- @end
  ANALYZE s01_22_custom;

  -- @step s01_22_held
  CREATE TEMP TABLE s01_22_held ON COMMIT DROP AS
  SELECT rp.organization_id, rp.role AS role_key, rp.action, rp.subject, rp.conditions
  FROM role_permissions rp
  JOIN s01_22_custom c ON c.organization_id = rp.organization_id AND c.role_key = rp.role;
  -- @end
  ANALYZE s01_22_held;

  -- @step s01_22_read
  CREATE TEMP TABLE s01_22_read ON COMMIT DROP AS
  SELECT x.organization_id, x.role_key, x.subject,
    CASE
      WHEN x.conditions IS NULL OR x.conditions = 'null'::jsonb THEN 'all'
      ELSE COALESCE((SELECT sh.class FROM s01_22_shape sh WHERE sh.subject = x.subject AND sh.cond = x.conditions LIMIT 1), 'other')
    END AS class
  FROM (
    SELECT organization_id, role AS role_key, subject, conditions
    FROM role_permissions
    WHERE role = 'SALES' AND action = 'read' AND subject IN ('Lead', 'Job', 'Estimate', 'Invoice')
    UNION ALL
    SELECT organization_id, role_key, subject, conditions
    FROM s01_22_held
    WHERE action = 'read' AND subject IN ('Lead', 'Job', 'Estimate', 'Invoice')
  ) x;
  -- @end
  ANALYZE s01_22_read;

  -- @step s01_22_sales_scope
  CREATE TEMP TABLE s01_22_sales_scope ON COMMIT DROP AS
  SELECT r.organization_id, r.role_key, w.switch_key, r.class,
    CASE r.class
      WHEN 'all' THEN '"all"'::jsonb
      WHEN 'attached' THEN '"attached"'::jsonb
      ELSE (SELECT p.value FROM s01_22_pre p WHERE p.role_key = 'SALES' AND p.switch_key = w.switch_key)
    END AS value
  FROM s01_22_read r
  JOIN s01_22_scope_sw w ON w.subject = r.subject
  WHERE r.role_key = 'SALES' AND r.subject <> 'Lead';
  -- @end
  ANALYZE s01_22_sales_scope;

  -- @step s01_22_custom_scope
  CREATE TEMP TABLE s01_22_custom_scope ON COMMIT DROP AS
  SELECT c.organization_id, c.role_key, w.switch_key, r.class,
    CASE r.class
      WHEN 'all' THEN '"all"'::jsonb
      WHEN 'attached' THEN '"attached"'::jsonb
      WHEN 'own_leads' THEN CASE WHEN w.keeps_own_leads THEN '"through_own_leads"'::jsonb END
    END AS value
  FROM s01_22_custom c
  JOIN s01_22_read r ON r.organization_id = c.organization_id AND r.role_key = c.role_key
  JOIN s01_22_scope_sw w ON w.subject = r.subject;
  -- @end
  ANALYZE s01_22_custom_scope;

  -- @step s01_22_custom_base
  CREATE TEMP TABLE s01_22_custom_base ON COMMIT DROP AS
  SELECT c.organization_id, c.role_key, w.switch_key,
    CASE WHEN c.made_from_blank THEN w.narrowest ELSE p.value END AS value
  FROM s01_22_custom c
  CROSS JOIN s01_22_sw w
  LEFT JOIN s01_22_pre p ON p.role_key = c.base_role AND p.switch_key = w.switch_key;
  -- @end
  ANALYZE s01_22_custom_base;

  -- @step s01_22_custom_raw
  CREATE TEMP TABLE s01_22_custom_raw ON COMMIT DROP AS
  SELECT b.organization_id, b.role_key, b.switch_key, b.value AS prev_value,
    CASE
      WHEN sc.value IS NOT NULL THEN sc.value
      WHEN src.action IS NOT NULL THEN to_jsonb(EXISTS (
        SELECT 1 FROM s01_22_held h
        WHERE h.organization_id = b.organization_id AND h.role_key = b.role_key AND h.action = src.action AND h.subject = src.subject))
      ELSE b.value
    END AS value
  FROM s01_22_custom_base b
  LEFT JOIN s01_22_src src ON src.switch_key = b.switch_key
  LEFT JOIN s01_22_custom_scope sc ON sc.organization_id = b.organization_id AND sc.role_key = b.role_key AND sc.switch_key = b.switch_key;
  -- @end
  ANALYZE s01_22_custom_raw;

  -- @step s01_22_custom_settled_1
  CREATE TEMP TABLE s01_22_custom_settled_1 ON COMMIT DROP AS
  SELECT r.organization_id, r.role_key, r.switch_key, r.prev_value,
    CASE WHEN r.value = 'true'::jsonb AND (COALESCE(m.missing, 0) > 0 OR (a.switch_key IS NOT NULL AND NOT a.any_on))
         THEN 'false'::jsonb ELSE r.value END AS value
  FROM s01_22_custom_raw r
  LEFT JOIN (
    SELECT n.organization_id, n.role_key, q.switch_key, count(*) FILTER (WHERE n.value IS DISTINCT FROM 'true'::jsonb) AS missing
    FROM s01_22_req q JOIN s01_22_custom_raw n ON n.switch_key = q.needed_key
    WHERE NOT q.any_of
    GROUP BY n.organization_id, n.role_key, q.switch_key
  ) m ON m.organization_id = r.organization_id AND m.role_key = r.role_key AND m.switch_key = r.switch_key
  LEFT JOIN (
    SELECT n.organization_id, n.role_key, q.switch_key, bool_or(n.value = 'true'::jsonb) AS any_on
    FROM s01_22_req q JOIN s01_22_custom_raw n ON n.switch_key = q.needed_key
    WHERE q.any_of
    GROUP BY n.organization_id, n.role_key, q.switch_key
  ) a ON a.organization_id = r.organization_id AND a.role_key = r.role_key AND a.switch_key = r.switch_key;
  -- @end
  ANALYZE s01_22_custom_settled_1;

  -- @step s01_22_custom_settled_2
  CREATE TEMP TABLE s01_22_custom_settled_2 ON COMMIT DROP AS
  SELECT r.organization_id, r.role_key, r.switch_key, r.prev_value,
    CASE WHEN r.value = 'true'::jsonb AND (COALESCE(m.missing, 0) > 0 OR (a.switch_key IS NOT NULL AND NOT a.any_on))
         THEN 'false'::jsonb ELSE r.value END AS value
  FROM s01_22_custom_settled_1 r
  LEFT JOIN (
    SELECT n.organization_id, n.role_key, q.switch_key, count(*) FILTER (WHERE n.value IS DISTINCT FROM 'true'::jsonb) AS missing
    FROM s01_22_req q JOIN s01_22_custom_settled_1 n ON n.switch_key = q.needed_key
    WHERE NOT q.any_of
    GROUP BY n.organization_id, n.role_key, q.switch_key
  ) m ON m.organization_id = r.organization_id AND m.role_key = r.role_key AND m.switch_key = r.switch_key
  LEFT JOIN (
    SELECT n.organization_id, n.role_key, q.switch_key, bool_or(n.value = 'true'::jsonb) AS any_on
    FROM s01_22_req q JOIN s01_22_custom_settled_1 n ON n.switch_key = q.needed_key
    WHERE q.any_of
    GROUP BY n.organization_id, n.role_key, q.switch_key
  ) a ON a.organization_id = r.organization_id AND a.role_key = r.role_key AND a.switch_key = r.switch_key;
  -- @end
  ANALYZE s01_22_custom_settled_2;

  -- @step s01_22_role_plan
  CREATE TEMP TABLE s01_22_role_plan ON COMMIT DROP AS
  SELECT u.organization_id, u.role_key, u.switch_key, u.value, u.prev_value, u.is_custom,
    (s.id IS NOT NULL) AS stored
  FROM (
    SELECT b.organization_id, b.role_key, p.switch_key, COALESCE(sc.value, p.value) AS value, p.value AS prev_value, false AS is_custom
    FROM s01_22_builtin b
    JOIN s01_22_pre p ON p.role_key = b.role_key
    LEFT JOIN s01_22_sales_scope sc ON sc.organization_id = b.organization_id AND sc.role_key = b.role_key AND sc.switch_key = p.switch_key
    UNION ALL
    SELECT organization_id, role_key, switch_key, value, prev_value, true FROM s01_22_custom_settled_2
  ) u
  LEFT JOIN permission_role_switches s
    ON s.organization_id = u.organization_id AND s.role_key = u.role_key AND s.switch_key = u.switch_key;
  -- @end
  ANALYZE s01_22_role_plan;

  -- @step s01_22_people
  CREATE TEMP TABLE s01_22_people ON COMMIT DROP AS
  SELECT u.id AS user_id, u.organization_id, COALESCE(cr.key, u.role::text) AS role_key,
    COALESCE(u.based_on_role_key, cr.key, u.role::text) AS prior_key
  FROM users u
  LEFT JOIN custom_roles cr ON cr.id = u.custom_role_id
  WHERE NOT (u.role = 'ADMIN' AND u.custom_role_id IS NULL);
  -- @end
  ANALYZE s01_22_people;

  -- @step s01_22_role_keys
  CREATE TEMP TABLE s01_22_role_keys ON COMMIT DROP AS
  SELECT organization_id, role_key FROM s01_22_people UNION SELECT organization_id, prior_key FROM s01_22_people;
  -- @end
  ANALYZE s01_22_role_keys;

  -- @step s01_22_role_eff
  CREATE TEMP TABLE s01_22_role_eff ON COMMIT DROP AS
  SELECT k.organization_id, k.role_key, w.switch_key,
    COALESCE(st.value, fb.value) AS before_value,
    COALESCE(st.value, rp.value, fb.value) AS after_value
  FROM s01_22_role_keys k
  CROSS JOIN s01_22_sw w
  LEFT JOIN custom_roles cr ON cr.organization_id = k.organization_id AND cr.key = k.role_key
  LEFT JOIN s01_22_pre fbp ON fbp.role_key = COALESCE(cr.base_role::text, k.role_key) AND fbp.switch_key = w.switch_key
  CROSS JOIN LATERAL (SELECT CASE WHEN cr.made_from_blank THEN w.narrowest ELSE fbp.value END AS value) fb
  LEFT JOIN permission_role_switches st
    ON st.organization_id = k.organization_id AND st.role_key = k.role_key AND st.switch_key = w.switch_key
  LEFT JOIN s01_22_role_plan rp
    ON rp.organization_id = k.organization_id AND rp.role_key = k.role_key AND rp.switch_key = w.switch_key AND NOT rp.stored;
  -- @end
  ANALYZE s01_22_role_eff;

  -- @step s01_22_user_plan
  CREATE TEMP TABLE s01_22_user_plan ON COMMIT DROP AS
  SELECT p.user_id, p.organization_id, a.switch_key, a.after_value AS value,
    COALESCE(o.value, b.before_value) AS prev_value, o.value AS own_value
  FROM s01_22_people p
  JOIN s01_22_role_eff a ON a.organization_id = p.organization_id AND a.role_key = p.role_key
  LEFT JOIN s01_22_role_eff b ON b.organization_id = p.organization_id AND b.role_key = p.prior_key AND b.switch_key = a.switch_key
  LEFT JOIN permission_user_switches o ON o.user_id = p.user_id AND o.switch_key = a.switch_key;
  -- @end
  ANALYZE s01_22_user_plan;

  -- @step s01_22_log_plan
  CREATE TEMP TABLE s01_22_log_plan ON COMMIT DROP AS
  SELECT organization_id, 'ROLE'::text AS target_type, role_key AS target_id, switch_key, prev_value AS from_value, value AS to_value
  FROM s01_22_role_plan
  WHERE NOT stored AND prev_value IS DISTINCT FROM value
  UNION ALL
  SELECT organization_id, 'USER', user_id::text, switch_key, prev_value, value
  FROM s01_22_user_plan
  WHERE prev_value IS DISTINCT FROM value;
  -- @end
  ANALYZE s01_22_log_plan;

  -- @step s01_22_dropped
  CREATE TEMP TABLE s01_22_dropped ON COMMIT DROP AS
  SELECT h.organization_id, c.custom_role_id, h.action, h.subject
  FROM s01_22_held h
  JOIN s01_22_custom c ON c.organization_id = h.organization_id AND c.role_key = h.role_key
  WHERE NOT EXISTS (SELECT 1 FROM s01_22_mapped m WHERE m.action = h.action AND m.subject = h.subject);
  -- @end
  ANALYZE s01_22_dropped;

  -- @step s01_22_ignored_overrides
  CREATE TEMP TABLE s01_22_ignored_overrides ON COMMIT DROP AS
  SELECT o.organization_id, o.user_id, o.action, o.subject, o.effect
  FROM user_permission_overrides o
  JOIN s01_22_people p ON p.user_id = o.user_id;
  -- @end
  ANALYZE s01_22_ignored_overrides;

  -- @step s01_22_report
  CREATE TEMP TABLE s01_22_report ON COMMIT DROP AS
  SELECT o.id AS organization_id,
    COALESCE(rr.rows_to_write, 0) AS role_rows_to_write,
    COALESCE(cr.custom_roles, 0) AS custom_roles_translated,
    COALESCE(sc.unknown_shapes, 0) AS sales_unknown_shapes,
    COALESCE(pp.people, 0) AS people_filled,
    COALESCE(up.people_changed, 0) AS people_changed,
    COALESCE(up.rows_to_write, 0) AS user_rows_to_write,
    COALESCE(lg.entries, 0) AS log_entries,
    COALESCE(dr.dropped, 0) AS dropped_grants,
    COALESCE(ov.ignored, 0) AS overrides_ignored
  FROM organizations o
  LEFT JOIN (SELECT organization_id, count(*) AS rows_to_write FROM s01_22_role_plan WHERE NOT stored GROUP BY organization_id) rr ON rr.organization_id = o.id
  LEFT JOIN (SELECT organization_id, count(*) AS custom_roles FROM s01_22_custom GROUP BY organization_id) cr ON cr.organization_id = o.id
  LEFT JOIN (SELECT organization_id, count(*) AS unknown_shapes FROM s01_22_sales_scope WHERE class = 'other' GROUP BY organization_id) sc ON sc.organization_id = o.id
  LEFT JOIN (SELECT organization_id, count(*) AS people FROM s01_22_people GROUP BY organization_id) pp ON pp.organization_id = o.id
  LEFT JOIN (
    SELECT organization_id, count(DISTINCT user_id) FILTER (WHERE prev_value IS DISTINCT FROM value) AS people_changed,
           count(*) FILTER (WHERE own_value IS DISTINCT FROM value) AS rows_to_write
    FROM s01_22_user_plan GROUP BY organization_id) up ON up.organization_id = o.id
  LEFT JOIN (SELECT organization_id, count(*) AS entries FROM s01_22_log_plan GROUP BY organization_id) lg ON lg.organization_id = o.id
  LEFT JOIN (SELECT organization_id, count(*) AS dropped FROM s01_22_dropped GROUP BY organization_id) dr ON dr.organization_id = o.id
  LEFT JOIN (SELECT organization_id, count(*) AS ignored FROM s01_22_ignored_overrides GROUP BY organization_id) ov ON ov.organization_id = o.id;
  -- @end
  ANALYZE s01_22_report;

  -- Before writing: what each organization has, and what this run will do about it.
  FOR rec IN SELECT * FROM s01_22_report WHERE role_rows_to_write > 0 OR people_changed > 0 OR custom_roles_translated > 0
                    OR dropped_grants > 0 OR overrides_ignored > 0 OR sales_unknown_shapes > 0 ORDER BY organization_id LOOP
    RAISE NOTICE 'S01.22 org %: role rows to write %, custom roles translated %, sales unknown shapes %, people filled %, people changed %, person rows to write %, log entries %, dropped grants %, overrides ignored %',
      rec.organization_id, rec.role_rows_to_write, rec.custom_roles_translated, rec.sales_unknown_shapes, rec.people_filled,
      rec.people_changed, rec.user_rows_to_write, rec.log_entries, rec.dropped_grants, rec.overrides_ignored;
  END LOOP;
  SELECT count(*) INTO planned FROM s01_22_log_plan;
  RAISE NOTICE 'S01.22 totals: organizations %, role rows to write %, custom roles translated %, people filled %, person rows to write %, log entries %',
    (SELECT count(*) FROM s01_22_report),
    (SELECT COALESCE(sum(role_rows_to_write), 0) FROM s01_22_report),
    (SELECT COALESCE(sum(custom_roles_translated), 0) FROM s01_22_report),
    (SELECT COALESCE(sum(people_filled), 0) FROM s01_22_report),
    (SELECT COALESCE(sum(user_rows_to_write), 0) FROM s01_22_report),
    planned;

  INSERT INTO permission_role_switches (id, organization_id, role_key, switch_key, value, created_at, updated_at)
  SELECT gen_random_uuid(), organization_id, role_key, switch_key, value, now(), now()
  FROM s01_22_role_plan
  WHERE NOT stored
  ON CONFLICT (organization_id, role_key, switch_key) DO NOTHING;

  INSERT INTO permission_user_switches (id, organization_id, user_id, switch_key, value, created_at, updated_at)
  SELECT gen_random_uuid(), organization_id, user_id, switch_key, value, now(), now()
  FROM s01_22_user_plan
  WHERE own_value IS DISTINCT FROM value
  ON CONFLICT (user_id, switch_key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();

  UPDATE users u SET based_on_role_key = p.role_key
  FROM s01_22_people p
  WHERE u.id = p.user_id AND u.based_on_role_key IS DISTINCT FROM p.role_key;

  INSERT INTO permission_change_log (id, organization_id, target_type, target_id, switch_key, from_value, to_value, actor_id, reason, created_at)
  SELECT gen_random_uuid(), organization_id, target_type, target_id, switch_key, from_value, to_value, NULL, 'migration', now()
  FROM s01_22_log_plan;
  GET DIAGNOSTICS logged = ROW_COUNT;

  -- After writing: every planned row is there with its planned value, every person is based on their role, and the
  -- log holds what was planned. Anything else rolls the whole migration back.
  SELECT count(*) INTO missing FROM s01_22_role_plan p
  WHERE NOT EXISTS (SELECT 1 FROM permission_role_switches s
                    WHERE s.organization_id = p.organization_id AND s.role_key = p.role_key AND s.switch_key = p.switch_key
                      AND (p.stored OR s.value = p.value));
  IF missing > 0 THEN
    RAISE EXCEPTION 'S01.22: % planned role rows did not land', missing;
  END IF;
  SELECT count(*) INTO missing FROM s01_22_user_plan p
  WHERE NOT EXISTS (SELECT 1 FROM permission_user_switches s
                    WHERE s.user_id = p.user_id AND s.switch_key = p.switch_key AND s.value = p.value);
  IF missing > 0 THEN
    RAISE EXCEPTION 'S01.22: % planned person rows did not land', missing;
  END IF;
  SELECT count(*) INTO missing FROM s01_22_people p
  WHERE NOT EXISTS (SELECT 1 FROM users u WHERE u.id = p.user_id AND u.based_on_role_key = p.role_key);
  IF missing > 0 THEN
    RAISE EXCEPTION 'S01.22: % people were not based on their role', missing;
  END IF;
  IF logged <> planned THEN
    RAISE EXCEPTION 'S01.22: % of % planned log entries landed', logged, planned;
  END IF;
  RAISE NOTICE 'S01.22 proof: every planned row landed (% log entries)', logged;
END
$s01_22$;
